247	                    .param("id", order.id()).param("pos", position++).param("sku", item.sku())
248	                    .param("q", item.quantity()).update();
249	        }
250	    }
251	
252	    public Optional<StoredOrder> find(String id) {
253	        return jdbc.sql(SELECT).param("id", id).query(this::map).optional().map(this::withItems);
254	    }
255	
256	    /** Reads the order locking its row until the end of the transaction. */
257	    public Optional<StoredOrder> findForUpdate(String id) {
258	        return jdbc.sql(SELECT + " FOR UPDATE").param("id", id).query(this::map).optional().map(this::withItems);
259	    }
260	
261	    public void updateStatus(String id, OrderStatus status) {
262	        jdbc.sql("UPDATE orders SET status = :s WHERE id = :id").param("s", status.name()).param("id", id).update();
263	    }
264	
265	    public void updateShipment(String id, String trackingCode) {
266	        jdbc.sql("UPDATE orders SET status = :s, tracking_code = :t WHERE id = :id")
267	                .param("s", OrderStatus.SHIPPED.name()).param("t", trackingCode).param("id", id).update();
268	    }
269	
270	    /** Whether the customer has an order that was paid, shipped or delivered. */
271	    public boolean hasPaidOrder(String cpf) {
272	        return jdbc.sql("SELECT COUNT(*) FROM orders WHERE cpf = :cpf AND status IN ('PAID', 'SHIPPED', 'DELIVERED')")
273	                .param("cpf", cpf).query(Long.class).single() > 0;
274	    }
275	
276	    public Optional<String> findPaymentOutcome(String orderId, String transactionId) {
277	        return jdbc.sql("SELECT outcome FROM payment_events WHERE order_id = :o AND transaction_id = :t")
278	                .param("o", orderId).param("t", transactionId).query(String.class).optional();
279	    }
280	
281	    public void recordPaymentOutcome(String orderId, String transactionId, String outcome) {
282	        jdbc.sql("INSERT INTO payment_events (order_id, transaction_id, outcome) VALUES (:o, :t, :out)")
283	                .param("o", orderId).param("t", transactionId).param("out", outcome).update();
284	    }
285	
286	    private StoredOrder withItems(StoredOrder stored) {
287	        Order o = stored.order();
288	        List<Order.Item> items = jdbc.sql("SELECT sku, quantity FROM order_items WHERE order_id = :id ORDER BY position")
289	                .param("id", o.id()).query((rs, n) -> new Order.Item(rs.getString("sku"), rs.getInt("quantity")))
290	                .list();
291	        return new StoredOrder(stored.cpf(), new Order(o.id(), o.status(), o.createdAt(), o.summary(), items,
292	                o.trackingCode()));
293	    }
294	
295	    private StoredOrder map(ResultSet rs, int row) throws SQLException {
296	        OrderSummary summary = new OrderSummary(money(rs, "products_subtotal"), money(rs, "coupon_discount"),
297	                money(rs, "shipping_cost"), rs.getInt("delivery_days"), money(rs, "insurance"),
298	                money(rs, "payment_adjustment"), money(rs, "final_total"), rs.getInt("installments"),
299	                money(rs, "installment_amount"), money(rs, "next_purchase_credit"), rs.getBoolean("gift"));
300	        Instant createdAt = rs.getObject("created_at", OffsetDateTime.class).toInstant();
301	        Order order = new Order(rs.getString("id"), OrderStatus.valueOf(rs.getString("status")), createdAt, summary,
302	                List.of(), rs.getString("tracking_code"));
303	        return new StoredOrder(rs.getString("cpf"), order);
304	    }
305	
306	    private static java.math.BigDecimal money(ResultSet rs, String column) throws SQLException {
307	        return rs.getBigDecimal(column).setScale(2);
308	    }
309	}

