208	import java.math.BigDecimal;
209	import java.net.URI;
210	import java.net.URLEncoder;
211	import java.net.http.HttpClient;
212	import java.net.http.HttpRequest;
213	import java.net.http.HttpResponse;
214	import java.nio.charset.StandardCharsets;
215	import java.time.Duration;
216	import java.util.Map;
217	import java.util.concurrent.CompletableFuture;
218	import java.util.concurrent.TimeUnit;
219	import org.slf4j.Logger;
220	import org.slf4j.LoggerFactory;
221	import org.springframework.beans.factory.annotation.Value;
222	import org.springframework.stereotype.Component;
223	import tools.jackson.databind.json.JsonMapper;
224	
225	@Component
226	public class TranslogClient implements CarrierGateway {
227	
228	    private static final Logger log = LoggerFactory.getLogger(TranslogClient.class);
229	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
230	
231	    private final String baseUrl;
232	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
233	    private final JsonMapper mapper = JsonMapper.builder().build();
234	
235	    public TranslogClient(@Value("${translog.url:}") String baseUrl) {
236	        String url = baseUrl == null ? "" : baseUrl.trim();
237	        this.baseUrl = url.endsWith("/") ? url.substring(0, url.length() - 1) : url;
238	    }
239	
240	    @Override
241	    public CarrierResult quote(String zipCode, long weightGrams, ServiceLevel level) {
242	        if (baseUrl.isEmpty()) {
243	            log.warn("TRANSLOG_URL is not set");
244	            return new Unavailable();
245	        }
246	        CompletableFuture<HttpResponse<String>> pending = null;
247	        try {
248	            String service = level == ServiceLevel.EXPRESS ? "EXP" : "STD";
249	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
250	                    + "&weight_g=" + weightGrams + "&service=" + service);
251	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
252	            pending = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
253	            HttpResponse<String> response = pending.get(TIMEOUT.toMillis(), TimeUnit.MILLISECONDS);
254	            if (response.statusCode() != 200) {
255	                return new Unavailable();
256	            }
257	            return parse(response.body());
258	        } catch (InterruptedException e) {
259	            Thread.currentThread().interrupt();
260	            return new Unavailable();
261	        } catch (RuntimeException | java.util.concurrent.ExecutionException
262	                | java.util.concurrent.TimeoutException e) {
263	            log.warn("TransLog quote failed: {}", e.toString());
264	            return new Unavailable();
265	        } finally {
266	            if (pending != null && !pending.isDone()) {
267	                pending.cancel(true);
268	            }
269	        }
270	    }
271	
272	    private CarrierResult parse(String body) {
273	        Map<?, ?> json = mapper.readValue(body, Map.class);
274	        Object error = json.get("error");
275	        if (error != null) {
276	            return "ZIP_NOT_SERVED".equals(error) ? new NotServed() : new Unavailable();
277	        }
278	        if (json.get("price_cents") instanceof Number cents && json.get("eta_hours") instanceof Number eta
279	                && isIntegral(cents) && isIntegral(eta) && cents.longValue() >= 0 && eta.longValue() >= 0) {
280	            return new Quoted(BigDecimal.valueOf(cents.longValue(), 2), eta.longValue());
281	        }
282	        return new Unavailable();
283	    }
284	
285	    private static boolean isIntegral(Number n) {
286	        return n instanceof Integer || n instanceof Long || n instanceof Short || n instanceof Byte;
287	    }
288	}
