295	/** Delivery priced and timed by an external carrier; the dispatch delay of the region is added on top. */
296	public class CarrierShippingOption implements ShippingOption {
297	
298	    private final String code;
299	    private final ServiceLevel level;
300	    private final CarrierGateway carrier;
301	
302	    public CarrierShippingOption(String code, ServiceLevel level, CarrierGateway carrier) {
303	        this.code = code;
304	        this.level = level;
305	        this.carrier = carrier;
306	    }
307	
308	    @Override
309	    public String code() {
310	        return code;
311	    }
312	
313	    @Override
314	    public ShippingQuote quote(ShippingRequest request) {
315	        long grams = request.weightKg().multiply(BigDecimal.valueOf(1000)).setScale(0, RoundingMode.CEILING)
316	                .longValueExact();
317	        return switch (carrier.quote(request.zipCode(), grams, level)) {
318	            case CarrierGateway.Quoted q -> new ShippingQuote(q.price(),
319	                    (int) ((q.etaHours() + 23) / 24) + request.region().dispatchDelayDays());
320	            case CarrierGateway.NotServed n -> throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
321	            case CarrierGateway.Unavailable u -> throw new ApiException("CARRIER_UNAVAILABLE", 503);
322	        };
323	    }
324	}
