524	        BigDecimal weight = rs.getBigDecimal("weight_kg").stripTrailingZeros();
525	        if (weight.scale() < 2) {
526	            weight = weight.setScale(2);
527	        }
528	        return new Product(rs.getString("sku"), rs.getString("name"), rs.getBigDecimal("price").setScale(2),
