  4	import org.springframework.stereotype.Component;
  5	
  6	@Component
  7	class CustomerCreditListener implements OrderLifecycleListener {
  8	
  9	    private final CustomerRepository customers;
 10	
 11	    CustomerCreditListener(CustomerRepository customers) {
 12	        this.customers = customers;
 13	    }
 14	
 15	    @Override
 16	    public void onPaid(StoredOrder order) {
 17	        customers.addCredit(order.cpf(), order.order().summary().nextPurchaseCredit());
 18	    }
 19	
 20	    @Override
 21	    public void onCancelled(StoredOrder order, boolean wasPaid) {
 22	        if (wasPaid) {
 23	            customers.addCredit(order.cpf(), order.order().summary().nextPurchaseCredit().negate());
 24	        }
 25	    }
 26	}
