331	import java.math.BigDecimal;
332	import java.math.MathContext;
333	import java.math.RoundingMode;
334	import org.springframework.stereotype.Component;
335	
336	@Component
337	public class CreditCardPayment implements PaymentMethod {
338	
339	    private static final int INTEREST_FREE_UP_TO = 3;
340	    private static final int MAX_INSTALLMENTS = 12;
341	    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.0199");
342	
343	    @Override
344	    public String code() {
345	        return "CREDIT_CARD";
346	    }
347	
348	    @Override
349	    public boolean allowsInstallments(int installments) {
350	        return installments >= 1 && installments <= MAX_INSTALLMENTS;
351	    }
352	
353	    @Override
354	    public PaymentCharge charge(BigDecimal orderTotal, int installments, boolean couponInformed) {
355	        BigDecimal n = BigDecimal.valueOf(installments);
356	        if (installments <= INTEREST_FREE_UP_TO) {
357	            return new PaymentCharge(orderTotal, orderTotal.divide(n, 2, RoundingMode.HALF_EVEN));
358	        }
359	        // Price table: total × i ÷ (1 − (1 + i)^−n)
360	        MathContext mc = MathContext.DECIMAL128;
361	        BigDecimal discount = BigDecimal.ONE.divide(BigDecimal.ONE.add(MONTHLY_RATE).pow(installments, mc), mc);
362	        BigDecimal installment = Money.round(orderTotal.multiply(MONTHLY_RATE)
363	                .divide(BigDecimal.ONE.subtract(discount), mc));
364	        return new PaymentCharge(installment.multiply(n), installment);
365	    }
366	}
